   887  /*
   888   * getIDWithAttrMask - Determines the ID of an instruction, consuming
   889   *   the ModR/M byte as appropriate for extended and escape opcodes,
   890   *   and using a supplied attribute mask.
   891   *
   892   * @param instructionID - A pointer whose target is filled in with the ID of the
   893   *                        instruction.
   894   * @param insn          - The instruction whose ID is to be determined.
   895   * @param attrMask      - The attribute mask to search.
   896   * @return              - 0 if the ModR/M could be read when needed or was not
   897   *                        needed; nonzero otherwise.
   898   */
   899  static int getIDWithAttrMask(uint16_t *instructionID,
   900                               struct InternalInstruction* insn,
   901                               uint16_t attrMask)
   902  {
   903          bool hasModRMExtension;
   904
   905          InstructionContext instructionClass = contextForAttrs(attrMask);
   906
   907          hasModRMExtension = modRMRequired(insn->opcodeType,
   908                          instructionClass,
   909                          insn->opcode);
   910
   911          if (hasModRMExtension) {
   912                  if (readModRM(insn))
   913                          return -1;
   914
   915                  *instructionID = decode(insn->opcodeType,
   916                                  instructionClass,
   917                                  insn->opcode,
   918                                  insn->modRM);
   919          } else {
   920                  *instructionID = decode(insn->opcodeType,
   921                                  instructionClass,
   922                                  insn->opcode,
   923                                  0);
   924          }
   925
   926          return 0;
   927  }
