  1168                          if (!is64Bit(instructionIDWithREXW)) {
  1169                                  insn->instructionID = instructionIDWithREXW;
  1170                                  insn->spec = specifierForUID(instructionIDWithREXW);
  1171
  1172                                  return 0;
  1173                          }
