  1177          /*
  1178           * Absolute moves, umonitor, and movdir64b need special handling.
  1179           * -For 16-bit mode because the meaning of the AdSize and OpSize prefixes are
  1180           *  inverted w.r.t.
  1181           * -For 32-bit mode we need to ensure the ADSIZE prefix is observed in
  1182           *  any position.
  1183           */
  1184          if ((insn->opcodeType == ONEBYTE && ((insn->opcode & 0xFC) == 0xA0)) ||
  1185                          (insn->opcodeType == TWOBYTE && (insn->opcode == 0xAE)) ||
  1186                          (insn->opcodeType == THREEBYTE_38 && insn->opcode == 0xF8)) {
  1187                  /* Make sure we observed the prefixes in any position. */
  1188                  if (insn->hasAdSize)
  1189                          attrMask |= ATTR_ADSIZE;
  1190
  1191                  if (insn->hasOpSize)
  1192                          attrMask |= ATTR_OPSIZE;
  1193
  1194                  /* In 16-bit, invert the attributes. */
  1195                  if (insn->mode == MODE_16BIT) {
  1196                          attrMask ^= ATTR_ADSIZE;
  1197
  1198                          /* The OpSize attribute is only valid with the absolute moves. */
  1199                          if (insn->opcodeType == ONEBYTE && ((insn->opcode & 0xFC) == 0xA0))
  1200                                  attrMask ^= ATTR_OPSIZE;
  1201                  }
  1202
  1203                  if (getIDWithAttrMask(&instructionID, insn, attrMask))
  1204                          return -1;
  1205
  1206                  insn->instructionID = instructionID;
  1207                  insn->spec = specifierForUID(instructionID);
  1208
  1209                  return 0;
  1210          }
  1211
  1212          if ((insn->mode == MODE_16BIT || insn->hasOpSize) &&
  1213                          !(attrMask & ATTR_OPSIZE)) {
  1214                  /*
  1215                   * The instruction tables make no distinction between instructions that
  1216                   * allow OpSize anywhere (i.e., 16-bit operations) and that need it in a
  1217                   * particular spot (i.e., many MMX operations).  In general we're
  1218                   * conservative, but in the specific case where OpSize is present but not
  1219                   * in the right place we check if there's a 16-bit operation.
  1220                   */
  1221                  const struct InstructionSpecifier *spec;
  1222                  uint16_t instructionIDWithOpsize;
  1223
  1224                  spec = specifierForUID(instructionID);
  1225
  1226                  if (getIDWithAttrMask(&instructionIDWithOpsize,
  1227                                          insn,
  1228                                          attrMask | ATTR_OPSIZE)) {
  1229                          /*
  1230                           * ModRM required with OpSize but not present; give up and return version
  1231                           * without OpSize set
  1232                           */
  1233                          insn->instructionID = instructionID;
  1234                          insn->spec = spec;
  1235
  1236                          return 0;
  1237                  }
  1238
  1239                  if (is16BitEquivalent(instructionID, instructionIDWithOpsize) &&
  1240                                  (insn->mode == MODE_16BIT) ^ insn->hasOpSize) {
  1241                          insn->instructionID = instructionIDWithOpsize;
  1242                          insn->spec = specifierForUID(instructionIDWithOpsize);
  1243                  } else {
  1244                          insn->instructionID = instructionID;
  1245                          insn->spec = spec;
  1246                  }
  1247
  1248                  return 0;
  1249          }
  1250
  1251          if (insn->opcodeType == ONEBYTE && insn->opcode == 0x90 &&
  1252                          insn->rexPrefix & 0x01) {
  1253                  /*
  1254                   * NOOP shouldn't decode as NOOP if REX.b is set. Instead
  1255                   * it should decode as XCHG %r8, %eax.
  1256                   */
  1257                  const struct InstructionSpecifier *spec;
  1258                  uint16_t instructionIDWithNewOpcode;
  1259                  const struct InstructionSpecifier *specWithNewOpcode;
  1260
  1261                  spec = specifierForUID(instructionID);
  1262
  1263                  /* Borrow opcode from one of the other XCHGar opcodes */
  1264                  insn->opcode = 0x91;
  1265
  1266                  if (getIDWithAttrMask(&instructionIDWithNewOpcode, insn, attrMask)) {
  1267                          insn->opcode = 0x90;
  1268
  1269                          insn->instructionID = instructionID;
  1270                          insn->spec = spec;
  1271
  1272                          return 0;
  1273                  }
  1274
  1275                  specWithNewOpcode = specifierForUID(instructionIDWithNewOpcode);
  1276
  1277                  /* Change back */
  1278                  insn->opcode = 0x90;
  1279
  1280                  insn->instructionID = instructionIDWithNewOpcode;
  1281                  insn->spec = specWithNewOpcode;
  1282
  1283                  return 0;
  1284          }
  1285
  1286          insn->instructionID = instructionID;
  1287          insn->spec = specifierForUID(insn->instructionID);
  1288
  1289          return 0;
  1290  }
